<?php
 declare(strict_types=1); function galonku_build_info(): array { static $cache = null; if ($cache !== null) { return $cache; } $defaults = [ 'hash' => 'dev', 'branch' => 'dev', 'timestamp' => null, 'dirty' => false, ]; $buildFile = dirname(__DIR__) . '/build-info.php'; if (is_file($buildFile)) { try { $info = require $buildFile; if (is_array($info)) { $merged = $info + $defaults; return $cache = $merged; } } catch (\Throwable $e) { } } $dir = __DIR__; while ($dir !== dirname($dir) && !is_dir($dir . '/.git')) { $dir = dirname($dir); } if (!is_dir($dir . '/.git')) { return $cache = $defaults; } [$hash, $hCode] = galonku_run_git('rev-parse --short HEAD', $dir); [$branch] = galonku_run_git('rev-parse --abbrev-ref HEAD', $dir); [$status] = galonku_run_git('status --porcelain', $dir); return $cache = [ 'hash' => $hCode === 0 && $hash !== '' ? $hash : 'dev', 'branch' => $branch !== '' ? $branch : 'dev', 'timestamp' => null, 'dirty' => $status !== '', ]; } function galonku_version_string(): string { $info = galonku_build_info(); $v = $info['hash']; if ($info['dirty']) { $v .= '-dirty'; } return $v; } function galonku_version_title(): string { $info = galonku_build_info(); $parts = []; if ($info['branch'] !== '' && $info['branch'] !== 'dev') { $parts[] = 'branch: ' . $info['branch']; } if ($info['timestamp'] !== null && $info['timestamp'] !== '') { $parts[] = 'built: ' . $info['timestamp']; } if ($info['dirty']) { $parts[] = 'uncommitted changes'; } return $parts !== [] ? implode(' · ', $parts) : 'development build'; } function galonku_run_git(string $args, string $cwd): array { $desc = [1 => ['pipe', 'w'], 2 => ['pipe', 'w']]; $pipes = []; $proc = @proc_open('git ' . $args, $desc, $pipes, $cwd); if (!is_resource($proc) || !isset($pipes[1], $pipes[2])) { return ['', 1]; } $stdout = stream_get_contents($pipes[1]); fclose($pipes[1]); fclose($pipes[2]); $code = proc_close($proc); return [trim((string) $stdout), $code]; } 